import json
import re
from pathlib import Path
from typing import Dict, List, Tuple


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    header_re = re.compile(r"^\s*\[([^\]]+)\]\s*$")

    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []
    node_index: Dict[str, int] = {}
    order: List[str] = []

    current_id: str | None = None
    entries: List[Dict[str, str]] = []

    def commit_section():
        nonlocal entries, current_id
        if current_id is None:
            entries = []
            return
        if not entries:
            # Empty node definition; create a placeholder line node
            node = {"id": current_id, "text": "", "speaker": "", "type": "line"}
            if current_id not in node_index:
                node_index[current_id] = len(nodes)
                nodes.append(node)
                order.append(current_id)
            entries = []
            return

        has_choice = any(e["kind"] == "choice" for e in entries)
        if has_choice:
            node = {"id": current_id, "text": "", "speaker": "", "type": "choice"}
        else:
            # Collapse multiple lines if present
            speaker = entries[0].get("speaker", "")
            texts: List[str] = []
            multi_speaker = False
            for e in entries:
                if e.get("speaker", "") != speaker:
                    multi_speaker = True
                texts.append(e.get("text", ""))
            if multi_speaker:
                speaker = ""
                texts = [
                    f"{e.get('speaker', '').strip()}: {e.get('text', '').strip()}".strip()
                    for e in entries
                ]
            text = "\n".join(texts).strip()
            node = {"id": current_id, "text": text, "speaker": speaker, "type": "line"}

        if current_id not in node_index:
            node_index[current_id] = len(nodes)
            nodes.append(node)
            order.append(current_id)
        else:
            nodes[node_index[current_id]] = node

        # Build edges
        for e in entries:
            target = e.get("target", "")
            if not target:
                continue
            if e["kind"] == "choice":
                edge_text = e.get("text", "")
            else:
                edge_text = ""
            edges.append({"from": current_id, "to": target, "text": edge_text})

        entries = []

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        header_match = header_re.match(line)
        if header_match:
            commit_section()
            current_id = header_match.group(1).strip()
            continue

        # Try to parse lines with explicit arrow first
        if "->" in line:
            left, target = [part.strip() for part in line.rsplit("->", 1)]
            if left:
                choice_match = re.match(r"^\s*(\d+)\.\s*(.+)$", left)
                if choice_match:
                    entries.append({
                        "kind": "choice",
                        "text": choice_match.group(2).strip(),
                        "target": target,
                    })
                    continue
                if ":" in left:
                    speaker, text_part = left.split(":", 1)
                    entries.append({
                        "kind": "line",
                        "speaker": speaker.strip(),
                        "text": text_part.strip(),
                        "target": target,
                    })
                    continue
                # Fallback: treat as a line without a speaker
                entries.append({
                    "kind": "line",
                    "speaker": "",
                    "text": left.strip(),
                    "target": target,
                })
                continue

        # Lines without arrows are treated as text-only line entries
        if ":" in line:
            speaker, text_part = line.split(":", 1)
            entries.append({
                "kind": "line",
                "speaker": speaker.strip(),
                "text": text_part.strip(),
                "target": "",
            })
        else:
            entries.append({
                "kind": "line",
                "speaker": "",
                "text": line.strip(),
                "target": "",
            })

    commit_section()

    # Add stub nodes for missing targets
    existing_ids = {n["id"] for n in nodes}
    for edge in edges:
        target = edge["to"]
        if target and target not in existing_ids:
            stub = {"id": target, "text": "", "speaker": "", "type": "line"}
            node_index[target] = len(nodes)
            nodes.append(stub)
            order.append(target)
            existing_ids.add(target)

    # Ensure all nodes are reachable from the first node
    if nodes:
        start_id = nodes[0]["id"]
        adjacency: Dict[str, List[str]] = {}
        for edge in edges:
            adjacency.setdefault(edge["from"], []).append(edge["to"])
        reachable = set()
        stack = [start_id]
        while stack:
            node_id = stack.pop()
            if node_id in reachable:
                continue
            reachable.add(node_id)
            for nxt in adjacency.get(node_id, []):
                if nxt not in reachable:
                    stack.append(nxt)

        nodes = [n for n in nodes if n["id"] in reachable]
        edges = [e for e in edges if e["from"] in reachable and e["to"] in reachable]

    return {"nodes": nodes, "edges": edges}


def _dot_escape(text: str) -> str:
    return text.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n")


def graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines = ["digraph Dialogue {"]
    lines.append("  rankdir=LR;")
    lines.append("  node [shape=box];")

    for node in graph.get("nodes", []):
        node_id = _dot_escape(node["id"])
        label_parts = [node["id"]]
        if node.get("type") == "choice":
            label_parts.append("(choice)")
        else:
            speaker = node.get("speaker", "").strip()
            text = node.get("text", "").strip()
            if speaker:
                label_parts.append(f"{speaker}: {text}")
            elif text:
                label_parts.append(text)
        label = _dot_escape("\n".join(label_parts))
        lines.append(f"  \"{node_id}\" [label=\"{label}\"]; ")

    for edge in graph.get("edges", []):
        frm = _dot_escape(edge["from"])
        to = _dot_escape(edge["to"])
        edge_text = edge.get("text", "")
        if edge_text:
            label = _dot_escape(edge_text)
            lines.append(f"  \"{frm}\" -> \"{to}\" [label=\"{label}\"]; ")
        else:
            lines.append(f"  \"{frm}\" -> \"{to}\";")

    lines.append("}")
    return "\n".join(lines)


def main() -> None:
    script_path = Path("/app/script.txt")
    out_json = Path("/app/dialogue.json")
    out_dot = Path("/app/dialogue.dot")

    text = script_path.read_text(encoding="utf-8")
    graph = parse_script(text)

    out_json.write_text(json.dumps(graph, indent=2, ensure_ascii=True), encoding="utf-8")
    out_dot.write_text(graph_to_dot(graph), encoding="utf-8")


if __name__ == "__main__":
    main()
